//! Material 3 Expressive 35 Shapes & Morphing Engine.
//! Exact Android 15/16 Jetpack Compose morph math.

use gpui::{Bounds, PathBuilder, Pixels, Rgba, Window, point, px, size};

/// Number of perimeter sample points used to represent each normalized shape.
pub const SHAPE_SAMPLE_COUNT: usize = 180;

/// The 35 official Material 3 Expressive shapes from AndroidX.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MaterialShape {
    /// The `Circle` shape.
    Circle,
    /// The `Square` shape.
    Square,
    /// The `Slanted` shape.
    Slanted,
    /// The `Arch` shape.
    Arch,
    /// The `Fan` shape.
    Fan,
    /// The `Arrow` shape.
    Arrow,
    /// The `SemiCircle` shape.
    SemiCircle,
    /// The `Oval` shape.
    Oval,
    /// The `Pill` shape.
    Pill,
    /// The `Triangle` shape.
    Triangle,
    /// The `Diamond` shape.
    Diamond,
    /// The `ClamShell` shape.
    ClamShell,
    /// The `Pentagon` shape.
    Pentagon,
    /// The `Gem` shape.
    Gem,
    /// The `Sunny` shape.
    Sunny,
    /// The `VerySunny` shape.
    VerySunny,
    /// The `Cookie4Sided` shape.
    Cookie4Sided,
    /// The `Cookie6Sided` shape.
    Cookie6Sided,
    /// The `Cookie7Sided` shape.
    Cookie7Sided,
    /// The `Cookie9Sided` shape.
    Cookie9Sided,
    /// The `Cookie12Sided` shape.
    Cookie12Sided,
    /// The `Ghostish` shape.
    Ghostish,
    /// The `Clover4Leaf` shape.
    Clover4Leaf,
    /// The `Clover8Leaf` shape.
    Clover8Leaf,
    /// The `Burst` shape.
    Burst,
    /// The `SoftBurst` shape.
    SoftBurst,
    /// The `Boom` shape.
    Boom,
    /// The `SoftBoom` shape.
    SoftBoom,
    /// The `Flower` shape.
    Flower,
    /// The `Puffy` shape.
    Puffy,
    /// The `PuffyDiamond` shape.
    PuffyDiamond,
    /// The `PixelCircle` shape.
    PixelCircle,
    /// The `PixelTriangle` shape.
    PixelTriangle,
    /// The `Bun` shape.
    Bun,
    /// The `Heart` shape.
    Heart,
}

