/// Convert a damping ratio (`zeta`) and stiffness (`k`) into a damping coefficient (`c`).
///
/// Uses the harmonic oscillator relation `c = 2 * zeta * sqrt(k)` for unit mass.
/// The indeterminate indicator motion uses `zeta = 0.6` with `k = 200.0`.
///
/// # Examples
///
/// ```rust
/// use gpui_material::shape::damping_from_ratio;
///
/// let c = damping_from_ratio(200.0, 0.6);
/// assert!((c - 16.97).abs() < 0.05);
/// ```
#[inline]
#[must_use]
pub fn damping_from_ratio(stiffness: f32, damping_ratio: f32) -> f32 {
    2.0 * damping_ratio * stiffness.max(1e-4).sqrt()
}

/// Interpolate two normalized point sets and rotate the result about the unit center.
///
/// Both inputs are borrowed slices (`own-borrow-over-clone`) and the result is a
/// stack-allocated fixed array, so per-frame evaluation performs zero heap
/// allocation. Rotation is clockwise in degrees around `(0.5, 0.5)`.
///
/// # Examples
///
/// ```rust
/// use gpui_material::shape::{MaterialShape, lerp_and_rotate_points};
///
/// let p0 = MaterialShape::Pill.points();
/// let p1 = MaterialShape::Sunny.points();
/// let mid = lerp_and_rotate_points(p0, p1, 0.5, 45.0);
/// assert_eq!(mid.len(), 180);
/// ```
#[inline]
#[must_use]
pub fn lerp_and_rotate_points(
    p0: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    p1: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    progress: f32,
    angle_deg: f32,
) -> [[f32; 2]; SHAPE_SAMPLE_COUNT] {
    let t = progress.clamp(0.0, 1.0);
    let one_minus_t = 1.0 - t;
    let theta = angle_deg.to_radians();
    let (sin, cos) = theta.sin_cos();
    let mut out = [[0.0f32; 2]; SHAPE_SAMPLE_COUNT];
    for i in 0..SHAPE_SAMPLE_COUNT {
        let x = one_minus_t * p0[i][0] + t * p1[i][0] - 0.5;
        let y = one_minus_t * p0[i][1] + t * p1[i][1] - 0.5;
        out[i][0] = 0.5 + x * cos - y * sin;
        out[i][1] = 0.5 + x * sin + y * cos;
    }
    out
}

/// Draw a static Material 3 Expressive shape filled with the given color.
pub fn draw_shape(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    shape: MaterialShape,
    color: Rgba,
) {
    draw_points(window, bounds, shape.points(), color);
}

/// Draw an interpolated morph between two sets of 180 normalized points with separate monotonic morph progress and physical bounce scaling.
pub fn draw_morph_with_bounce(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    p0: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    p1: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    morph_t: f32,
    spring_pos: f32,
    color: Rgba,
) {
    let t = morph_t.clamp(0.0, 1.0);
    // If spring overshoots, simulate elastic physical bounce via scale factor
    // as specified in Android Jetpack Compose LoadingIndicator / ShapeUtil:
    // "Use the coerced progress value to eliminate any bounciness from the morph.
    // We scale the drawing to simulate some bounciness instead."
    let scale = if (spring_pos - 1.0).abs() > 1e-4 {
        1.0 + (spring_pos - 1.0) * 0.12
    } else {
        1.0
    };

    let target_bounds = if (scale - 1.0).abs() > 1e-4 {
        let cx = bounds.left() + bounds.size.width / 2.0;
        let cy = bounds.top() + bounds.size.height / 2.0;
        let sw = bounds.size.width * scale;
        let sh = bounds.size.height * scale;
        Bounds {
            origin: point(cx - sw / 2.0, cy - sh / 2.0),
            size: size(sw, sh),
        }
    } else {
        bounds
    };

    if t >= 0.9999 {
        draw_points(window, target_bounds, p1, color);
        return;
    }
    if t <= 0.0001 {
        draw_points(window, target_bounds, p0, color);
        return;
    }
    let mut morphed = [[0.0f32; 2]; SHAPE_SAMPLE_COUNT];
    let one_minus_t = 1.0 - t;
    for i in 0..SHAPE_SAMPLE_COUNT {
        morphed[i][0] = one_minus_t * p0[i][0] + t * p1[i][0];
        morphed[i][1] = one_minus_t * p0[i][1] + t * p1[i][1];
    }
    draw_points(window, target_bounds, &morphed, color);
}

/// Draw an interpolated morph between two sets of 180 normalized points at progress t.
pub fn draw_morph_points(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    p0: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    p1: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    progress: f32,
    color: Rgba,
) {
    draw_morph_with_bounce(window, bounds, p0, p1, progress.clamp(0.0, 1.0), progress, color);
}

/// Draw an interpolated morph between two shapes with separate monotonic morph progress and physical bounce scaling.
pub fn draw_shape_morph_with_bounce(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    from: MaterialShape,
    to: MaterialShape,
    morph_t: f32,
    spring_pos: f32,
    color: Rgba,
) {
    if from == to {
        let scale = if (spring_pos - 1.0).abs() > 1e-4 {
            1.0 + (spring_pos - 1.0) * 0.12
        } else {
            1.0
        };
        let target_bounds = if (scale - 1.0).abs() > 1e-4 {
            let cx = bounds.left() + bounds.size.width / 2.0;
            let cy = bounds.top() + bounds.size.height / 2.0;
            let sw = bounds.size.width * scale;
            let sh = bounds.size.height * scale;
            Bounds {
                origin: point(cx - sw / 2.0, cy - sh / 2.0),
                size: size(sw, sh),
            }
        } else {
            bounds
        };
        draw_shape(window, target_bounds, to, color);
        return;
    }
    draw_morph_with_bounce(window, bounds, from.points(), to.points(), morph_t, spring_pos, color);
}

/// Draw an interpolated morph between two shapes at progress t.
pub fn draw_morph(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    from: MaterialShape,
    to: MaterialShape,
    progress: f32,
    color: Rgba,
) {
    draw_shape_morph_with_bounce(window, bounds, from, to, progress.clamp(0.0, 1.0), progress, color);
}

/// Draw a closed polygon from 180 normalized unit coordinates [0, 1].
///
/// Skips painting entirely when `bounds` lies fully outside the viewport,
/// so scrolled-away shapes cost no path tessellation or raster work.
pub fn draw_points(
    window: &mut Window,
    bounds: Bounds<Pixels>,
    points: &[[f32; 2]; SHAPE_SAMPLE_COUNT],
    color: Rgba,
) {
    let viewport = window.viewport_size();
    if bounds.right() < px(0.0)
        || bounds.left() > viewport.width
        || bounds.bottom() < px(0.0)
        || bounds.top() > viewport.height
    {
        return;
    }
    let w = f32::from(bounds.size.width);
    let h = f32::from(bounds.size.height);
    let ox = bounds.left();
    let oy = bounds.top();
    let mut builder = PathBuilder::fill();
    builder.move_to(point(ox + px(points[0][0] * w), oy + px(points[0][1] * h)));
    for pt in &points[1..] {
        builder.line_to(point(ox + px(pt[0] * w), oy + px(pt[1] * h)));
    }
    builder.close();
    if let Ok(path) = builder.build() {
        window.paint_path(path, color);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_35_shapes_present_and_unique() {
        assert_eq!(MaterialShape::ALL.len(), 35);
        for (i, s) in MaterialShape::ALL.iter().enumerate() {
            assert_eq!(*s as usize, i);
            assert!(!s.name().is_empty());
            assert!(!s.short_name().is_empty());
        }
    }

    #[test]
    fn shape_coordinates_within_unit_bounds() {
        for s in MaterialShape::ALL {
            let pts = s.points();
            assert_eq!(pts.len(), SHAPE_SAMPLE_COUNT);
            for pt in pts {
                assert!(
                    pt[0] >= -0.01 && pt[0] <= 1.01,
                    "Shape {:?} x coordinate out of bounds: {}",
                    s,
                    pt[0]
                );
                assert!(
                    pt[1] >= -0.01 && pt[1] <= 1.01,
                    "Shape {:?} y coordinate out of bounds: {}",
                    s,
                    pt[1]
                );
            }
        }
    }

    #[test]
    fn arch_is_upright_tombstone() {
        // Reference glyph: flat bottom, straight sides, arched top, symmetric
        // about x = 0.5 with the apex centered at the top.
        let pts = MaterialShape::Arch.points();
        let max_y = pts.iter().map(|p| p[1]).fold(f32::NEG_INFINITY, f32::max);
        let min_y = pts.iter().map(|p| p[1]).fold(f32::INFINITY, f32::min);
        // Flat bottom: a wide run of points sharing max y.
        let bottom: Vec<_> = pts.iter().filter(|p| max_y - p[1] < 0.004).collect();
        assert!(bottom.len() >= 8, "arch bottom not flat: {}", bottom.len());
        let bottom_span =
            bottom.iter().map(|p| p[0]).fold(f32::NEG_INFINITY, f32::max)
                - bottom.iter().map(|p| p[0]).fold(f32::INFINITY, f32::min);
        assert!(bottom_span > 0.4, "arch bottom too narrow: {bottom_span}");
        // Apex centered at the top.
        let apex = pts
            .iter()
            .min_by(|a, b| a[1].total_cmp(&b[1]))
            .expect("arch has points");
        assert!((apex[0] - 0.5).abs() < 0.02, "arch apex off-center: {:?}", apex);
        assert!(min_y < 0.06, "arch apex too low: {min_y}");
        // Vertical mirror symmetry.
        for p in pts {
            let mirror = pts
                .iter()
                .map(|q| (q[0] - (1.0 - p[0])).abs() + (q[1] - p[1]).abs())
                .fold(f32::INFINITY, f32::min);
            assert!(mirror < 0.01, "arch not symmetric at {p:?}");
        }
    }

    #[test]
    fn morph_interpolation_preserves_bounds() {
        let arch = MaterialShape::Arch.points();
        let fan = MaterialShape::Fan.points();
        for t in [0.0f32, 0.25, 0.5, 0.75, 1.0] {
            let one_minus_t = 1.0 - t;
            for i in 0..SHAPE_SAMPLE_COUNT {
                let x = one_minus_t * arch[i][0] + t * fan[i][0];
                let y = one_minus_t * arch[i][1] + t * fan[i][1];
                assert!((0.0..=1.0).contains(&x));
                assert!((0.0..=1.0).contains(&y));
            }
        }
    }
}

